{
  "case_id": "C08",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "What memory is",
      "narration": "When an infection clears, the body doesn't start from scratch next time. Some of the T cells that fought it stay on as a memory population, set to respond faster and larger on re-exposure.",
      "on_screen": "Simple timeline: infection, recovery, a small group of T cells remaining",
      "claim_refs": [
        "CL01"
      ]
    },
    {
      "beat": "Five years on",
      "narration": "In 302 adults, memory CD8+ T cells against one defined viral epitope were detectable in 88% of participants at 5 years, with a 95% confidence interval of 84 to 91.",
      "on_screen": "302 adults; 88% detectable at 5 years (95% CI 84 to 91)",
      "claim_refs": [
        "CL02"
      ]
    },
    {
      "beat": "Twelve years on",
      "narration": "By 12 years, detection in the same cohort was 61%, 95% CI 55 to 67. These populations decline over time.",
      "on_screen": "61% detectable at 12 years (95% CI 55 to 67); downward arrow from 88%",
      "claim_refs": [
        "CL03"
      ]
    },
    {
      "beat": "Speed on re-exposure",
      "narration": "In a subset of 34 re-exposed under a controlled protocol, secondary expansion was measured at 4.2-fold faster than the primary response, 95% CI 3.1 to 5.7 — like a runner who already knows the course, off the blocks sooner.",
      "on_screen": "n = 34; 4.2-fold faster than primary (95% CI 3.1 to 5.7)",
      "claim_refs": [
        "CL04"
      ]
    },
    {
      "beat": "What this does not say",
      "narration": "This is a review reporting one cohort: associations from one defined epitope, varying by pathogen and by individual. A participant counted as positive only above a fixed frequency threshold, so those percentages depend on where that cut-off sits — and detectable memory cells don't guarantee protection from disease.",
      "on_screen": "Caveats: review; single cohort; one epitope; varies by pathogen and individual; cohort-level, not an individual prediction; positive = above a fixed frequency threshold",
      "claim_refs": [
        "CL01",
        "CL02",
        "CL03",
        "CL04"
      ]
    }
  ]
}
